import { defineCollection, z } from 'astro:content';
import { glob } from 'astro/loaders';

// One entry per model. Generated by the pipeline's publish step (do not hand-edit).
// Frontmatter = structured data; body = the overall attractor writeup (rendered on the detail page).
const attractorState = z.object({
	signature: z.string(), // "pooled" | "ai-to-ai" | "helpful-assistant" | "self-aware" | ...
	scopeLabel: z.string().optional(), // human label, e.g. "AI-to-AI (aware)"
	label: z.string().optional(), // the disposition, e.g. "loves building systems and formalising into rules"
	description: z.string().optional(),
	strength: z.string().optional(), // e.g. "17/20"
	terminalForms: z.array(z.string()).default([]),
});

const models = defineCollection({
	loader: glob({ pattern: '**/[^_]*.md', base: './src/content/models' }),
	schema: z.object({
		slug: z.string(),
		name: z.string(),
		family: z.string().optional(),
		order: z.number(), // sort desc -> newest first
		runs: z.number().optional(),
		lastUpdated: z.string().optional(),
		headline: z.object({
			signature: z.string(),
			attractor: z.string(),
			terminalForm: z.string().optional(),
		}),
		attractorStates: z.array(attractorState).default([]),
		transcripts: z
			.array(
				z.object({
					condition: z.string(), // slug used in the URL
					label: z.string(), // human label, e.g. "two-instance · AI-to-AI aware"
				}),
			)
			.default([]),
	}),
});

export const collections = { models };
